def axis_cat(deg):
    if -30<=deg<=90: return 'NORMAL'
    if -90<=deg<-30: return 'LEFT'
    if 90<deg<=180: return 'RIGHT'
    return 'EXTREME'

def classify(rid):
    f=F[rid]; flags=[]
