    elif rmssd<80 and pamp>=0.08 and pc>=0.80 and f['pr_ms'] and 80<=f['pr_ms']<=330: rhythm='SINUS'
    else: rhythm='?'; flags.append('rhythm')
    if rmssd>=90 and rhythm!='AF': flags.append('irregular')
    if f['qrs_ms']>=110: flags.append('wideQRS')
    if f['n_spike']>=5 and f['spike_amp']>=20: flags.append('spikes')
    if f['t_lim']: flags.append('qtlim')
    if f['qtc_ms']>=480 or f['qtc_ms']<=330: flags.append('qtc')
    a1=axis_cat(f['axis_deg']); a2=axis_cat(f['axis_amp_deg'])
